function row(a) {
  const [slug, stage, title, minutes, summary, scenario, interviewer, p0, p1, p2, p3, p4, prompt, c0, c1, c2, c3, answer, explain] = a;
  return { slug, stage, title, minutes, summary, scenario, interviewer, playbook: [p0,p1,p2,p3,p4], prompt, choices: [c0,c1,c2,c3], answer, explain };
}
function track(slug, rows) {
  if (rows.length !== 10) throw new Error(slug + ' ' + rows.length);
  return [slug, rows.map(row)];
}
